window.AUTH=window.AUTH||{};window.AUTH["24-1238"]={"d":"24-1238","id":"2025/24-1238","n":"Montgomery v. Caribe Transport II, LLC","briefs":[{"k":"petitioner","label":"Brief of petitioner Shawn Montgomery","date":"2025-12-01","url":"https://www.supremecourt.gov/DocketPDF/24/24-1238/386022/20251201145245920_24-1238_Brief%20for%20Petitioner.pdf","side":"pet","n":80},{"k":"respondent","label":"Brief of respondents Caribe Transport II, LLC, et al.","date":"2026-01-14","url":"https://www.supremecourt.gov/DocketPDF/24/24-1238/391718/20260114133856784_Montgomery%20-%20Respondents%20Br..pdf","side":"res","n":119},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2026-01-21","url":"https://www.supremecourt.gov/DocketPDF/24/24-1238/392379/20260121162222044_24-1238bsacUSA_final.pdf","side":"us","n":61},{"k":"reply","label":"Reply of petitioner Shawn Montgomery","date":"2026-02-13","url":"https://www.supremecourt.gov/DocketPDF/24/24-1238/396222/20260213122048721_24-1238%20Final%20Montgomery%20Reply.pdf","side":"pet","n":19}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/608us1r32_g3bi.pdf","tr":true,"items":[{"t":"case","label":"Am. Airlines, Inc. v. Wolens","cite":"513 U.S. 219","y":1995,"id":"1994/93-1286","sc":1,"sum":"The Court held that the ADA bars state-imposed regulation of air carriers, thus claims brought under a state's consumer fraud act are preempted; but that the ADA allows room for court enforcement of contract terms set by the parties themselves, which permits breach of contract claims to proceed. \"A remedy confined to a contract's terms simply holds parties to their agreements -- in this instance, to business judgments an airline made public about its rates and services,\" wrote Justice Ginsburg.","sumSrc":"Oyez","by":{"0":"49","1":"17","2":"17, 19","3":"22"}},{"t":"case","label":"Aspen Am. Ins. Co. v. Landstar Ranger, Inc.","cite":"65 F.4th 1261","y":2023,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/65/1261/","op":2,"ar":1,"by":{"0":"28, 35, 37","1":"28, 30, 36","2":"10, 24"}},{"t":"case","label":"Bedoya v. Am. Eagle Express Inc.","cite":"914 F.3d 812","y":2019,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/914/812/","by":{"0":"40"}},{"t":"case","label":"BNSF Ry. Co. v. Loos","cite":"586 U.S. 310","y":2019,"id":"2018/17-1042","sc":1,"sum":"A railroad’s payment to an employee for working time lost due to an on-the-job injury is taxable “compensation” under the Railroad Retirement Tax Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"23"}},{"t":"case","label":"Bower v. Egyptair Airlines Co.","cite":"731 F.3d 85","y":2013,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/731/85/","sum":"Recognizing that “personal injury claims are generally not preempted by the ADA”.","sumSrc":"brief:0","by":{"0":"48","1":"17, 25"}},{"t":"case","label":"Branche v. Airtran Airways, Inc.","cite":"342 F.3d 1248","y":2003,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/342/1248/","by":{"0":"48, 49","2":"16"}},{"t":"case","label":"Campos-Chavez v. Garland","cite":"602 U.S. 447","y":2024,"url":"https://supreme.justia.com/cases/federal/us/602/447/","sc":1,"by":{"0":"18, 44"}},{"t":"case","label":"Charas v. Trans World Airlines, Inc.","cite":"160 F.3d 1259","y":1998,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/160/1259/","by":{"0":"48, 49","2":"16"}},{"t":"case","label":"Cipollone v. Liggett Grp., Inc.","cite":"505 U.S. 504","y":1992,"id":"1991/90-1038","sc":1,"sum":"In a complicated 7-to-2 decision, the Court held that federally mandated warnings do not bar smokers from suing manufacturers under state personal-injury laws. The justices ruled that such suits cannot be based on claims that cigarette advertising failed to warn smokers of smoking dangers.","sumSrc":"Oyez","by":{"0":"19","2":"11"}},{"t":"case","label":"City of Chicago v. Beretta U.S.A. Corp.","cite":"821 N.E.2d 1099","y":2004,"court":"Ill.","url":"https://www.courtlistener.com/c/N.E.2d/821/1099/","ar":1,"by":{"0":"29","3":"6"}},{"t":"case","label":"City of Columbus v. Ours Garage & Wrecker Serv., Inc.","cite":"536 U.S. 424","y":2002,"id":"2001/01-419","sc":1,"op":2,"sum":"The Court held that section 14501(c) does not bar a State from delegating to municipalities and other local units the State's authority to establish safety regulations governing motor carriers of property, including tow trucks. \"A locality, as section 14501(c) recognizes, is a 'political subdivision' of the State,\" wrote Justice Ginsburg. \"Ordinarily, a political subdivision may exercise whatever portion of state power the State...chooses to delegate to the subdivision.","sumSrc":"Oyez","by":{"0":"8, 20, 24, 34","1":"4, 5, 46, 48","2":"6","3":"10, 19"}},{"t":"case","label":"Conn. Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37"}},{"t":"case","label":"Cox v. Total Quality Logistics, Inc.","cite":"142 F.4th 847","y":2025,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/142/847/","op":1,"sum":"Recognizing that this Court and lower courts “have consistently rejected the argument that a state’s regulatory authority can encompass only positive enactments of law”.","sumSrc":"brief:0","by":{"0":"19, 20, 23, 25, 27, 30, 34, 45","2":"10, 19","3":"2, 4, 9"}},{"t":"case","label":"Dan’s City Used Cars, Inc. v. Pelkey","cite":"569 U.S. 251","y":2013,"id":"2012/12-52","sc":1,"op":2,"sum":"Interpreting “with respect to the transportation of property”.","sumSrc":"opinion","by":{"0":"7, 22, 24, 26, 27, 47, 50","1":"9, 13, 27, 28, 32, 36","2":"5, 17-19, 21, 23, 25","3":"5, 8"}},{"t":"case","label":"Day v. SkyWest Airlines","cite":"45 F.4th 1181","y":2022,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/45/1181/","by":{"0":"6, 47, 49","2":"16","3":"23"}},{"t":"case","label":"Desiano v. Warner-Lambert & Co.","cite":"467 F.3d 85","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/467/85/","by":{"0":"19","2":"21"}},{"t":"case","label":"EEOC v. Abercrombie & Fitch Stores, Inc.","cite":"575 U.S. 768","y":2015,"id":"2014/14-86","sc":1,"sum":"The Court held that an employer may be held liable under Title VII of the Civil Rights Act if an applicant can show that her need for an accommodation was a motivating factor in the employer’s decision not to hire her.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Ellis & Lewis v. Warner","cite":"20 S.W.2d 320","y":1929,"court":"Ark.","url":"https://www.courtlistener.com/c/S.W.2d/20/320/","by":{"0":"39","1":"50"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"584 U.S. 79","y":2018,"id":"2017/16-1362","sc":1,"sum":"The Court decided that because service advisors at car dealerships are “salesm[e]n . . . primarily engaged in . . . servicing automobiles,” 29 U.S.C. § 213(b)(10)(A), they are exempt from the Fair Labor Standards Act's overtime-pay requirements.","sumSrc":"Oyez","by":{"0":"17, 44","3":"21"}},{"t":"case","label":"Feliciano v. Dep’t of Transp.","cite":"605 U.S. 38","y":2025,"url":"https://supreme.justia.com/cases/federal/us/605/38/","sc":1,"by":{"0":"42","1":"51"}},{"t":"case","label":"Glover v. Argonaut Ins. Co.","cite":"2025 WL 1805708","y":2025,"court":"M.D. La. June 30","by":{"0":"41"}},{"t":"case","label":"Hawkins v. Milan Express, Inc.","cite":"735 F. Supp. 3d 933","y":2024,"court":"E.D. Tenn.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/735/933/","by":{"0":"41"}},{"t":"case","label":"Hodges v. Delta Airlines, Inc.","cite":"44 F.3d 334","y":1995,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/44/334/","by":{"0":"48","2":"16","3":"23"}},{"t":"case","label":"Hudgens v. Cook Indus., Inc.","cite":"521 P.2d 813","y":1973,"court":"Okla.","url":"https://www.courtlistener.com/c/P.2d/521/813/","by":{"0":"39","1":"50"}},{"t":"case","label":"Kaipust v. Echo Glob. Logistics, Inc.","cite":"2025 WL 2374556","y":2025,"court":"Ill. App. Ct. Aug. 15","by":{"0":"13"}},{"t":"case","label":"Kurns v. R.R. Friction Prods. Corp.","cite":"565 U.S. 625","y":2012,"id":"2011/10-879","sc":1,"op":1,"sum":"The Court held that the Locomotive Inspection Act preempts state law design defect claims and state law failure to warn claims.","sumSrc":"Oyez","by":{"0":"19","2":"20"}},{"t":"case","label":"L.B. Foster Co. v. Hurnblad","cite":"418 F.2d 727","y":1969,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/418/727/","by":{"0":"39","1":"50"}},{"t":"case","label":"Marx v. Gen. Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"sum":"The Court held that the Federal Rules of Civil Procedure awards costs to the prevailing party unless a statute explicitly states otherwise.","sumSrc":"Oyez","by":{"0":"37","3":"10"}},{"t":"case","label":"McComb v. Bugarin","cite":"20 F. Supp. 3d 676","y":2014,"court":"N.D. Ill.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/20/676/","by":{"0":"22"}},{"t":"case","label":"Meek v. Toor","cite":"2024 WL 943931","y":2024,"court":"E.D. Tex. Mar. 5","by":{"0":"41"}},{"t":"case","label":"Miller v. C.H. Robinson Wordwide, Inc.","cite":"976 F.3d 1016","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/976/1016/","op":1,"by":{"0":"13, 20, 41","1":"20","2":"10, 11, 14, 16"}},{"t":"case","label":"Milne v. Move Freight Trucking, LLC","cite":"2024 WL 762373","y":2024,"court":"W.D. Va. Feb. 20","by":{"0":"41"}},{"t":"case","label":"Morales v. Trans World Airlines","cite":"504 U.S. 374","y":1992,"id":"1991/90-1604","sc":1,"ar":1,"sum":"The Court held that the Airline Deregulation Act of 1978 prevents states from prohibiting deceptive airline fare advertisements through enforcement of their general consumer protection statuses.","sumSrc":"Oyez","by":{"0":"5, 18","1":"23, 29, 36, 37","2":"4, 12, 15, 19"}},{"t":"case","label":"Mut. Pharm. Co. v. Bartlett","cite":"570 U.S. 472","y":2013,"id":"2012/12-142","sc":1,"sum":"The Court found that federal law preempts state law design-defect claims.","sumSrc":"Oyez","by":{"0":"19","2":"20"}},{"t":"case","label":"Northwest, Inc. v. Ginsberg","cite":"572 U.S. 273","y":2014,"id":"2013/12-462","sc":1,"sum":"The Court held that the Airline Deregulation Act preempts claims arising from a frequent flier complaint based on price, route, or air carrier service.","sumSrc":"Oyez","by":{"0":"5, 45","1":"16","2":"10"}},{"t":"case","label":"O’Gilvie v. United States","cite":"519 U.S. 79","y":1996,"id":"1996/95-966","sc":1,"sum":"The Court held that the punitive damages received by the O'Gilvies were not received \"on account of\" personal injuries,\" and therefore the provision did not apply and the damages were taxable.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Ortiz v. Ben Strong Trucking, Inc.","cite":"624 F. Supp. 3d 567","y":2022,"court":"D. Md.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/624/567/","by":{"0":"41"}},{"t":"case","label":"Presley v. Etowah Cnty. Comm’n","cite":"502 U.S. 491","y":1992,"id":"1991/90-711","sc":1,"ar":1,"sum":"In a majority opinion authored by Justice Anthony M. Kennedy, the Court determined that section 5 of the Voting Rights Act covers only changes that directly relate to voting.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Riegel v. Medtronic, Inc.","cite":"552 U.S. 312","y":2008,"id":"2007/06-179","sc":1,"sum":"The Court, in an 8-1 decision, affirmed the Second Circuit and granted summary judgment in favor of Medtronic. The Court's opinion, written by Justice Antonin Scalia, noted that the MDA pre-empted state common law claims for defective devices such as this one.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Risley v. Lenwell","cite":"277 P.2d 897","y":1954,"court":"Cal. Ct. App.","url":"https://www.courtlistener.com/c/P.2d/277/897/","by":{"0":"39","1":"50"}},{"t":"case","label":"Rowe v. N.H. Motor Transp. Ass’n","cite":"552 U.S. 364","y":2008,"id":"2007/06-457","sc":1,"ar":4,"sum":"The Court affirmed both lower courts, holding that the FAAAA preempted the state laws. In a unanimous decision written by Justice Stephen Breyer, the Court asserted that the state laws were directly connected with motor carrier services and therefore had a significant and adverse impact on the congressional goal of precluding state regulation in lieu of competitive market forces.","sumSrc":"Oyez","by":{"0":"8, 47","1":"4, 5, 11, 16, 21, 22, 37","2":"6, 11-15","3":"22"}},{"t":"case","label":"Taj Mahal Travel, Inc. v. Delta Airlines, Inc.","cite":"164 F.3d 186","y":1998,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/164/186/","by":{"0":"48","2":"16"}},{"t":"case","label":"Va. Uranium, Inc. v. Warren","cite":"587 U.S. 761","y":2019,"url":"https://supreme.justia.com/cases/federal/us/587/761/","sc":1,"by":{"0":"19"}},{"t":"case","label":"Van Horne v. Muller","cite":"705 N.E.2d 898","y":1998,"court":"Ill.","url":"https://www.courtlistener.com/c/N.E.2d/705/898/","by":{"0":"22, 28","2":"28"}},{"t":"case","label":"Wardingley v. Ecovyst Catalyst Techs., LLC","cite":"639 F. Supp. 3d 803","y":2022,"court":"N.D. Ind.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/639/803/","by":{"0":"41"}},{"t":"case","label":"Watson v. Air Methods Corp.","cite":"870 F.3d 812","y":2017,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/870/812/","sum":"Finding it “unlikely” that “personal-injury claims against air carriers based on unsafe operations or maintenance are expressly pre-empted by the ADA”.","sumSrc":"brief:0","by":{"0":"47","2":"16"}},{"t":"case","label":"West v. Gibson","cite":"527 U.S. 212","y":1999,"id":"1998/98-238","sc":1,"sum":"The Court held that the Equal Employment Opportunity Commission possess the legal authority to require federal agencies to pay compensatory damages when they discriminate in violation of Title VII of Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Wyeth v. Levine","cite":"555 U.S. 555","y":2009,"id":"2008/06-1249","sc":1,"sum":"The Court held that federal law did not preempt state law in a personal injury action against a drug manufacturer for failing to include an appropriate warning label, even where the drug in question met the Food and Drug Administration's (FDA) labeling requirements.","sumSrc":"Oyez","by":{"0":"19","1":"25","2":"21"}},{"t":"case","label":"Ye v. GlobalTranz Enterprises, Inc.","cite":"74 F.4th 453","y":2023,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/74/453/","op":4,"sum":"Recognizing that “many courts agree with” that proposition and finding “much to say in support of this argument”.","sumSrc":"brief:0","by":{"0":"14, 26, 27, 28, 29, 30, 31, 33, 34, 35, 49","1":"8-10, 16, 17, 20, 28, 38, 39, 41, 44","2":"7, 10, 13, 26","3":"9, 10, 12, 15"}},{"t":"usc","label":"49 U.S.C. § 13102","url":"https://www.law.cornell.edu/uscode/text/49/13102","subs":["(2)","(8)","(14)","(23)","(16)","(9)","(23)(B)"],"stext":{"head":"§13102. Definitions","paras":[[0,"In this part, the following definitions shall apply:"],[1,"(1) Board.—The term \"Board\" means the Surface Transportation Board."],[1,"(2) Broker.—The term \"broker\" means a person, other than a motor carrier or an employee or agent of a motor carrier, that as a principal or agent sells, offers for sale, negotiates for, or holds itself out by solicitation, advertisement, or otherwise as selling, providing, or arranging for, transportation by motor carrier for compensation."],[1,"(3) Carrier.—The term \"carrier\" means a motor carrier, a water carrier, and a freight forwarder."],[1,"(4) Contract carriage.—The term \"contract carriage\" means—"],[2,"(A) for transportation provided before January 1, 1996, service provided pursuant to a permit issued under section 10923, as in effect on December 31, 1995; and"],[2,"(B) for transportation provided after December 31, 1995, service provided under an agreement entered into under section 14101(b)."],[1,"(5) Control.—The term \"control\", when referring to a relationship between persons, includes actual control, legal control, and the power to exercise control, through or by—"],[2,"(A) common directors, officers, stockholders, a voting trust, or a holding or investment company, or"],[2,"(B) any other means."],[1,"(6) Foreign motor carrier.—The term \"foreign motor carrier\" means a person (including a motor carrier of property but excluding a motor private carrier)—"],[2,"(A)(i) that is domiciled in a contiguous foreign country; or"],[2,"(ii) that is owned or controlled by persons of a contiguous foreign country; and"],[2,"(B) in the case of a person that is not a motor carrier of property, that provides interstate transportation of property by motor vehicle under an agreement or contract entered into with a motor carrier of property (other than a motor private carrier or a motor carrier of property described in subparagraph (A))."],[1,"(7) Foreign motor private carrier.—The term \"foreign motor private carrier\" means a person (including a motor private carrier but excluding a motor carrier of property)—"],[2,"(A)(i) that is domiciled in a contiguous foreign country; or"],[2,"(ii) that is owned or controlled by persons of a contiguous foreign country; and"],[2,"(B) in the case of a person that is not a motor private carrier, that provides interstate transportation of property by motor vehicle under an agreement or contract entered into with a person (other than a motor carrier of property or a motor private carrier described in subparagraph (A))."],[1,"(8) Freight forwarder.—The term \"freight forwarder\" means a person holding itself out to the general public (other than as a pipeline, rail, motor, or water carrier) to provide transportation of property for compensation and in the ordinary course of its business—"],[2,"(A) assembles and consolidates, or provides for assembling and consolidating, shipments and performs or provides for break-bulk and distribution operations of the shipments;"],[2,"(B) assumes responsibility for the transportation from the place of receipt to the place of destination; and"],[2,"(C) uses for any part of the transportation a carrier subject to jurisdiction under this subtitle."],[1,"The term does not include a person using transportation of an air carrier subject to part A of subtitle VII."],[1,"(9) Highway.—The term \"highway\" means a road, highway, street, and way in a State."],[1,"(10) Household goods.—The term \"household goods\", as used in connection with transportation, means personal effects and property used or to be used in a dwelling, when a part of the equipment or supply of such dwelling, and similar property if the transportation of such effects or property is—"],[2,"(A) arranged and paid for by the householder, except such term does not include property moving from a factory or store, other than property that the householder has purchased with the intent to use in his or her dwelling and is transported at the request of, and the transportation charges are paid to the carrier by, the householder; or"],[2,"(B) arranged and paid for by another party."],[1,"(11) Household goods freight forwarder.—The term \"household goods freight forwarder\" means a freight forwarder of one or more of the following items: household goods, unaccompanied baggage, or used automobiles."],[1,"(12) Household goods motor carrier.—"],[2,"(A) In general.—The term \"household goods motor carrier\" means a motor carrier that, in the ordinary course of its business of providing transportation of household goods, offers some or all of the following additional services:"],[3,"(i) Binding and nonbinding estimates."],[3,"(ii) Inventorying."],[3,"(iii) Protective packing and unpacking of individual items at personal residences."],[3,"(iv) Loading and unloading at personal residences."],[2,"(B) Inclusion.—The term includes any person that is considered to be a household goods motor carrier under regulations, determinations, and decisions of the Federal Motor Carrier Safety Administration that are in effect on the date of enactment of the Household Goods Mover Oversight Enforcement and Reform Act of 2005."],[2,"(C) Limited service exclusion.—The term does not include a motor carrier when the motor carrier provides transportation of household goods in containers or trailers that are entirely loaded and unloaded by an individual (other than an employee or agent of the motor carrier)."],[1,"(13) Individual shipper.—The term \"individual shipper\" means any person who—"],[2,"(A) is the shipper, consignor, or consignee of a household goods shipment;"],[2,"(B) is identified as the shipper, consignor, or consignee on the face of the bill of lading;"],[2,"(C) owns the goods being transported; and"],[2,"(D) pays his or her own tariff transportation charges."],[1,"(14) Motor carrier.—The term \"motor carrier\" means a person providing motor vehicle transportation for compensation."],[1,"(15) Motor private carrier.—The term \"motor private carrier\" means a person, other than a motor carrier, transporting property by motor vehicle when—"],[2,"(A) the transportation is as provided in section 13501 of this title;"],[2,"(B) the person is the owner, lessee, or bailee of the property being transported; and"],[2,"(C) the property is being transported for sale, lease, rent, or bailment or to further a commercial enterprise."],[1,"(16) Motor vehicle.—The term \"motor vehicle\" means a vehicle, machine, tractor, trailer, or semitrailer propelled or drawn by mechanical power and used on a highway in transportation, or a combination determined by the Secretary, but does not include a vehicle, locomotive, or car operated only on a rail, or a trolley bus operated by electric power from a fixed overhead wire, and providing local passenger transportation similar to street-railway service."],[1,"(17) Noncontiguous domestic trade.—The term \"noncontiguous domestic trade\" means transportation subject to jurisdiction under chapter 135 involving traffic originating in or destined to Alaska, Hawaii, or a territory or possession of the United States."],[1,"(18) Person.—The term \"person\", in addition to its meaning under section 1 of title 1, includes a trustee, receiver, assignee, or personal representative of a person."],[1,"(19) Pre-arranged ground transportation service.—The term \"pre-arranged ground transportation service\" means transportation for a passenger (or a group of passengers) that is arranged in advance (or is operated on a regular route or between specified points) and is provided in a motor vehicle with a seating capacity not exceeding 15 passengers (including the driver)."],[1,"(20) Secretary.—The term \"Secretary\" means the Secretary of Transportation."],[1,"(21) State.—The term \"State\" means the 50 States of the United States and the District of Columbia."],[1,"(22) Taxicab service.—The term \"taxicab service\" means passenger transportation in a motor vehicle having a capacity of not more than 8 passengers (including the driver), not operated on a regular route or between specified places, and that—"],[2,"(A) is licensed as a taxicab by a State or a local jurisdiction; or"],[2,"(B) is offered by a person that—"],[3,"(i) provides local transportation for a fare determined (except with respect to transportation to or from airports) primarily on the basis of the distance traveled; and"],[3,"(ii) does not primarily provide transportation to or from airports."],[1,"(23) Transportation.—The term \"transportation\" includes—"],[2,"(A) a motor vehicle, vessel, warehouse, wharf, pier, dock, yard, property, facility, instrumentality, or equipment of any kind related to the movement of passengers or property, or both, regardless of ownership or an agreement concerning use; and"],[2,"(B) services related to that movement, including arranging for, receipt, delivery, elevation, transfer in transit, refrigeration, icing, ventilation, storage, handling, packing, unpacking, and interchange of passengers and property."],[1,"(24) United states.—The term \"United States\" means the States of the United States and the District of Columbia."],[1,"(25) Vessel.—The term \"vessel\" means a watercraft or other artificial contrivance that is used, is capable of being used, or is intended to be used, as a means of transportation by water."],[1,"(26) Water carrier.—The term \"water carrier\" means a person providing water transportation for compensation."],[1,"(27) Over-the-road bus.—The term \"over-the-road bus\" means a bus characterized by an elevated passenger deck located over a baggage compartment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/49/13102?type=usc&year=mostrecent&link-type=html"},"head":"§13102. Definitions","tname":"Transportation","by":{"0":"11, 15, 21, 36, 21, 35","1":"1, 7, 17, 18, 28, 44, 49, 1, 6, 35, 28, 28","2":"2, 8, 13, 19, 23, 24, 6, 24, 23, 24, 8, 18, 18, 27","3":"3, 3, 4"}},{"t":"usc","label":"49 U.S.C. § 13904","url":"https://www.law.cornell.edu/uscode/text/49/13904","subs":["(a)","(d)","(d)(1)","(e)"],"stext":{"head":"§13904. Registration of brokers","paras":[[0,"(a) In General.—The Secretary shall register, subject to section 13906(b), a person to be a broker for transportation of property subject to jurisdiction under subchapter I of chapter 135, if the Secretary determines that the person—"],[1,"(1) has sufficient experience to qualify the person to act as a broker for transportation; and"],[1,"(2) is fit, willing, and able to be a broker for transportation and to comply with this part and applicable regulations of the Secretary."],[0,"(b) Duration.—A registration issued under subsection (a) shall only remain in effect while the broker for transportation is in compliance with section 13906(b)."],[0,"(c) Experience or Training Requirements.—Each broker shall employ, as an officer, an individual who—"],[1,"(1) has at least 3 years of relevant experience; or"],[1,"(2) provides the Secretary with satisfactory evidence of the individual's knowledge of related rules, regulations, and industry practices."],[0,"(d) Registration as Motor Carrier Required.—"],[1,"(1) In general.—A broker for transportation may not provide transportation as a motor carrier unless the broker has registered separately under this chapter to provide transportation as a motor carrier."],[1,"(2) Limitation.—This subsection does not apply to a motor carrier registered under this chapter or to an employee or agent of the motor carrier to the extent the transportation is to be provided entirely by the motor carrier, with other registered motor carriers, or with rail or water carriers."],[0,"(e) Regulation to Protect Motor Carriers and Shippers.—Regulations of the Secretary applicable to brokers registered under this section shall provide for the protection of motor carriers and shippers by motor vehicle."],[0,"(f) Bond and Insurance.—The Secretary may impose on brokers for motor carriers of passengers such requirements for bonds or insurance or both as the Secretary determines are needed to protect passengers and carriers dealing with such brokers."],[0,"(g) Update of Registration.—The Secretary shall require a broker to update its registration under this section not later than 30 days after a change in the broker's address, other contact information, officers, process agent, or other essential information, as determined by the Secretary."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/49/13904?type=usc&year=mostrecent&link-type=html"},"head":"§13904. Registration of brokers","tname":"Transportation","by":{"0":"10","1":"7, 2, 8, 16, 23, 35, 6, 39, 40","2":"31"}},{"t":"usc","label":"49 U.S.C. § 13906","url":"https://www.law.cornell.edu/uscode/text/49/13906","subs":["(a)","(a)(1)","(b)","(b)(2)(A)","(b)(3)"],"stext":{"head":"§13906. Security of motor carriers, motor private carriers, brokers, and freight forwarders","paras":[[0,"(a) Motor Carrier Requirements.—"],[1,"(1) Liability insurance requirement.—The Secretary may register a motor carrier under section 13902 only if the registrant files with the Secretary a bond, insurance policy, or other type of security approved by the Secretary, in an amount not less than such amount as the Secretary prescribes pursuant to, or as is required by, sections 31138 and 31139, and the laws of the State or States in which the registrant is operating, to the extent applicable. The security must be sufficient to pay, not more than the amount of the security, for each final judgment against the registrant for bodily injury to, or death of, an individual resulting from the negligent operation, maintenance, or use of motor vehicles, or for loss or damage to property (except property referred to in paragraph (3) 1 of this subsection), or both. A registration remains in effect only as long as the registrant continues to satisfy the security requirements of this paragraph."],[1,"(2) Security requirement.—Not later than 120 days after the date of enactment of the Unified Carrier Registration Act of 2005, any person, other than a motor private carrier, registered with the Secretary to provide transportation or service as a motor carrier under section 13905(b) shall file with the Secretary a bond, insurance policy, or other type of security approved by the Secretary, in an amount not less than required by sections 31138 and 31139."],[1,"(3) Agency requirement.—A motor carrier shall comply with the requirements of sections 13303 and 13304. To protect the public, the Secretary may require any such motor carrier to file the type of security that a motor carrier is required to file under paragraph (1) of this subsection. This paragraph only applies to a foreign motor private carrier and foreign motor carrier operating in the United States to the extent that such carrier is providing transportation between places in a foreign country or between a place in one foreign country and a place in another foreign country."],[1,"(4) Transportation insurance.—The Secretary may require a registered motor carrier to file with the Secretary a type of security sufficient to pay a shipper or consignee for damage to property of the shipper or consignee placed in the possession of the motor carrier as the result of transportation provided under this part. A carrier required by law to pay a shipper or consignee for loss, damage, or default for which a connecting motor carrier is responsible is subrogated, to the extent of the amount paid, to the rights of the shipper or consignee under any such security."],[0,"(b) Broker Financial Security Requirements.—"],[1,"(1) Requirements.—"],[2,"(A) In general.—The Secretary may register a person as a broker under section 13904 only if the person files with the Secretary a surety bond, proof of trust fund, or other financial security, or a combination thereof, in a form and amount, and from a provider, determined by the Secretary to be adequate to ensure financial responsibility."],[2,"(B) Use of a group surety bond, trust fund, or other surety.—In implementing the standards established by subparagraph (A), the Secretary may authorize the use of a group surety bond, trust fund, or other financial security, or a combination thereof, that meets the requirements of this subsection."],[2,"(C) Proof of trust or other financial security.—For purposes of subparagraph (A), a trust fund or other financial security may be acceptable to the Secretary only if the trust fund or other financial security consists of assets readily available to pay claims without resort to personal guarantees or collection of pledged accounts receivable."],[1,"(2) Scope of financial responsibility.—"],[2,"(A) Payment of claims.—A surety bond, trust fund, or other financial security obtained under paragraph (1) shall be available to pay any claim against a broker arising from its failure to pay freight charges under its contracts, agreements, or arrangements for transportation subject to jurisdiction under chapter 135 if—"],[3,"(i) subject to the review by the surety provider, the broker consents to the payment;"],[3,"(ii) in any case in which the broker does not respond to adequate notice to address the validity of the claim, the surety provider determines that the claim is valid; or"],[3,"(iii) the claim is not resolved within a reasonable period of time following a reasonable attempt by the claimant to resolve the claim under clauses (i) and (ii), and the claim is reduced to a judgment against the broker."],[2,"(B) Response of surety providers to claims.—If a surety provider receives notice of a claim described in subparagraph (A), the surety provider shall—"],[3,"(i) respond to the claim on or before the 30th day following the date on which the notice was received; and"],[3,"(ii) in the case of a denial, set forth in writing for the claimant the grounds for the denial."],[2,"(C) Costs and attorney's fees.—In any action against a surety provider to recover on a claim described in subparagraph (A), the prevailing party shall be entitled to recover its reasonable costs and attorney's fees."],[1,"(3) Minimum financial security.—Each broker subject to the requirements of this section shall provide financial security of $75,000 for purposes of this subsection, regardless of the number of branch offices or sales agents of the broker."],[1,"(4) Cancellation notice.—If a financial security required under this subsection is canceled—"],[2,"(A) the holder of the financial security shall provide electronic notification to the Secretary of the cancellation not later than 30 days before the effective date of the cancellation; and"],[2,"(B) the Secretary shall immediately post such notification on the public Internet Website of the Department of Transportation."],[1,"(5) Suspension.—The Secretary shall immediately suspend the registration of a broker issued under this chapter if the available financial security of that person falls below the amount required under this subsection."],[1,"(6) Payment of claims in cases of financial failure or insolvency.—If a broker registered under this chapter experiences financial failure or insolvency, the surety provider of the broker shall—"],[2,"(A) submit a notice to cancel the financial security to the Administrator in accordance with paragraph (4);"],[2,"(B) publicly advertise for claims for 60 days beginning on the date of publication by the Secretary of the notice to cancel the financial security; and"],[2,"(C) pay, not later than 30 days after the expiration of the 60-day period for submission of claims—"],[3,"(i) all uncontested claims received during such period; or"],[3,"(ii) a pro rata share of such claims if the total amount of such claims exceeds the financial security available."],[1,"(7) Penalties.—"],[2,"(A) Civil actions.—Either the Secretary or the Attorney General of the United States may bring a civil action in an appropriate district court of the United States to enforce the requirements of this subsection or a regulation prescribed or order issued under this subsection. The court may award appropriate relief, including injunctive relief."],[2,"(B) Civil penalties.—If the Secretary determines, after notice and opportunity for a hearing, that a surety provider of a broker registered under this chapter has violated the requirements of this subsection or a regulation prescribed under this subsection, the surety provider shall be liable to the United States for a civil penalty in an amount not to exceed $10,000."],[2,"(C) Eligibility.—If the Secretary determines, after notice and opportunity for a hearing, that a surety provider of a broker registered under this chapter has violated the requirements of this subsection or a regulation prescribed under this subsection, the surety provider shall be ineligible to provider 2 broker financial security for 3 years."],[1,"(8) Deduction of costs prohibited.—The amount of the financial security required under this subsection may not be reduced by deducting attorney's fees or administrative costs."],[0,"(c) Freight Forwarder Financial Security Requirements.—"],[1,"(1) Requirements.—"],[2,"(A) In general.—The Secretary may register a person as a freight forwarder under section 13903 only if the person files with the Secretary a surety bond, proof of trust fund, other financial security, or a combination of such instruments, in a form and amount, and from a provider, determined by the Secretary to be adequate to ensure financial responsibility."],[2,"(B) Use of a group surety bond, trust fund, or other financial security.—In implementing the standards established under subparagraph (A), the Secretary may authorize the use of a group surety bond, trust fund, other financial security, or a combination of such instruments, that meets the requirements of this subsection."],[2,"(C) Surety bonds.—A surety bond obtained under this section may only be obtained from a bonding company that has been approved by the Secretary of the Treasury."],[2,"(D) Proof of trust or other financial security.—For purposes of subparagraph (A), a trust fund or other financial security may not be accepted by the Secretary unless the trust fund or other financial security consists of assets readily available to pay claims without resort to personal guarantees or collection of pledged accounts receivable."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/49/13906?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§13906. Security of motor carriers, motor private carriers, brokers, and freight forwarders","tname":"Transportation","by":{"0":"34","1":"6, 12, 25, 2, 39, 40, 2, 7, 12, 25, 40, 6","2":"17, 22, 26, 32, 26"}},{"t":"usc","label":"49 U.S.C. § 14501","url":"https://www.law.cornell.edu/uscode/text/49/14501","subs":["(a)","(a)(2)","(b)","(c)(1)","(c)(2)","(c)(2)(A)","(a)(1)","(c)","(b)(1)"],"stext":{"head":"§14501. Federal authority over intrastate transportation","paras":[[0,"(a) Motor Carriers of Passengers.—"],[1,"(1) Limitation on state law.—No State or political subdivision thereof and no interstate agency or other political agency of 2 or more States shall enact or enforce any law, rule, regulation, standard, or other provision having the force and effect of law relating to—"],[2,"(A) scheduling of interstate or intrastate transportation (including discontinuance or reduction in the level of service) provided by a motor carrier of passengers subject to jurisdiction under subchapter I of chapter 135 of this title on an interstate route;"],[2,"(B) the implementation of any change in the rates for such transportation or for any charter transportation except to the extent that notice, not in excess of 30 days, of changes in schedules may be required; or"],[2,"(C) the authority to provide intrastate or interstate charter bus transportation."],[1,"This paragraph shall not apply to intrastate commuter bus operations, or to intrastate bus transportation of any nature in the State of Hawaii."],[1,"(2) Matters not covered.—Paragraph (1) shall not restrict the safety regulatory authority of a State with respect to motor vehicles, the authority of a State to impose highway route controls or limitations based on the size or weight of the motor vehicle, or the authority of a State to regulate carriers with regard to minimum amounts of financial responsibility relating to insurance requirements and self-insurance authorization."],[0,"(b) Freight Forwarders and Brokers.—"],[1,"(1) General rule.—Subject to paragraph (2) of this subsection, no State or political subdivision thereof and no intrastate agency or other political agency of 2 or more States shall enact or enforce any law, rule, regulation, standard, or other provision having the force and effect of law relating to intrastate rates, intrastate routes, or intrastate services of any freight forwarder or broker."],[1,"(2) Continuation of hawaii's authority.—Nothing in this subsection and the amendments made by the Surface Freight Forwarder Deregulation Act of 1986 shall be construed to affect the authority of the State of Hawaii to continue to regulate a motor carrier operating within the State of Hawaii."],[0,"(c) Motor Carriers of Property.—"],[1,"(1) General rule.—Except as provided in paragraphs (2) and (3), a State, political subdivision of a State, or political authority of 2 or more States may not enact or enforce a law, regulation, or other provision having the force and effect of law related to a price, route, or service of any motor carrier (other than a carrier affiliated with a direct air carrier covered by section 41713(b)(4)) or any motor private carrier, broker, or freight forwarder with respect to the transportation of property."],[1,"(2) Matters not covered.—Paragraph (1)—"],[2,"(A) shall not restrict the safety regulatory authority of a State with respect to motor vehicles, the authority of a State to impose highway route controls or limitations based on the size or weight of the motor vehicle or the hazardous nature of the cargo, or the authority of a State to regulate motor carriers with regard to minimum amounts of financial responsibility relating to insurance requirements and self-insurance authorization;"],[2,"(B) does not apply to the intrastate transportation of household goods; and"],[2,"(C) does not apply to the authority of a State or a political subdivision of a State to enact or enforce a law, regulation, or other provision relating to the regulation of tow truck operations performed without the prior consent or authorization of the owner or operator of the motor vehicle."],[1,"(3) State standard transportation practices.—"],[2,"(A) Continuation.—Paragraph (1) shall not affect any authority of a State, political subdivision of a State, or political authority of 2 or more States to enact or enforce a law, regulation, or other provision, with respect to the intrastate transportation of property by motor carriers, related to—"],[3,"(i) uniform cargo liability rules,"],[3,"(ii) uniform bills of lading or receipts for property being transported,"],[3,"(iii) uniform cargo credit rules,"],[3,"(iv) antitrust immunity for joint line rates or routes, classifications, mileage guides, and pooling, or"],[3,"(v) antitrust immunity for agent-van line operations (as set forth in section 13907),"],[2,"if such law, regulation, or provision meets the requirements of subparagraph (B)."],[2,"(B) Requirements.—A law, regulation, or provision of a State, political subdivision, or political authority meets the requirements of this subparagraph if—"],[3,"(i) the law, regulation, or provision covers the same subject matter as, and compliance with such law, regulation, or provision is no more burdensome than compliance with, a provision of this part or a regulation issued by the Secretary or the Board under this part; and"],[3,"(ii) the law, regulation, or provision only applies to a carrier upon request of such carrier."],[2,"(C) Election.—Notwithstanding any other provision of law, a carrier affiliated with a direct air carrier through common controlling ownership may elect to be subject to a law, regulation, or provision of a State, political subdivision, or political authority under this paragraph."],[1,"(4) Nonapplicability to hawaii.—This subsection shall not apply with respect to the State of Hawaii."],[1,"(5) Limitation on statutory construction.—Nothing in this section shall be construed to prevent a State from requiring that, in the case of a motor vehicle to be towed from private property without the consent of the owner or operator of the vehicle, the person towing the vehicle have prior written authorization from the property owner or lessee (or an employee or agent thereof) or that such owner or lessee (or an employee or agent thereof) be present at the time the vehicle is towed from the property, or both."],[0,"(d) Pre-Arranged Ground Transportation.—"],[1,"(1) In general.—No State or political subdivision thereof and no interstate agency or other political agency of 2 or more States shall enact or enforce any law, rule, regulation, standard or other provision having the force and effect of law requiring a license or fee on account of the fact that a motor vehicle is providing pre-arranged ground transportation service if the motor carrier providing such service—"],[2,"(A) meets all applicable registration requirements under chapter 139 for the interstate transportation of passengers;"],[2,"(B) meets all applicable vehicle and intrastate passenger licensing requirements of the State or States in which the motor carrier is domiciled or registered to do business; and"],[2,"(C) is providing such service pursuant to a contract for—"],[3,"(i) transportation by the motor carrier from one State, including intermediate stops, to a destination in another State; or"],[3,"(ii) transportation by the motor carrier from one State, including intermediate stops in another State, to a destination in the original State."],[1,"(2) Intermediate stop defined.—In this section, the term \"intermediate stop\", with respect to transportation by a motor carrier, means a pause in the transportation in order for one or more passengers to engage in personal or business activity, but only if the driver providing the transportation to such passenger or passengers does not, before resuming the transportation of such passenger (or at least 1 of such passengers), provide transportation to any other person not included among the passengers being transported when the pause began."],[1,"(3) Matters not covered.—Nothing in this subsection shall be construed—"],[2,"(A) as subjecting taxicab service to regulation under chapter 135 or section 31138;"],[2,"(B) as prohibiting or restricting an airport, train, or bus terminal operator from contracting to provide preferential access or facilities to one or more providers of pre-arranged ground transportation service; and"],[2,"(C) as restricting the right of any State or political subdivision of a State to require, in a nondiscriminatory manner, that any individual operating a vehicle providing prearranged ground transportation service originating in the State or political subdivision have submitted to pre-licensing drug testing or a criminal background investigation of the records of the State in which the operator is domiciled, by the State or political subdivision by which the operator is licensed to provide such service, or by the motor carrier providing such service, as a condition of providing such service."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/49/14501?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§14501. Federal authority over intrastate transportation","tname":"Transportation","by":{"0":"8, 25, 32, 31, 1, 8, 22, 27, 30, 36, 44, 46, 21, 2, 8, 14, 18, 19, 20, 21, 23, 24, 30, 31, 32, 34, 35, 36, 37, 38, 40, 43, 46, 50, 30, 40","1":"44, 44, 7, 9, 37, 3, 5, 10, 15, 17, 23, 24, 5, 6, 10, 27, 29, 44, 46, 52","2":"3, 25, 25, 1, 29, 30, 2, 3, 5, 7-9, 11, 12, 15, 17-23, 25, 27-29, 6, 3, 4, 6-8, 20-23, 25-29","3":"1, 3, 4, 7, 18"}},{"t":"usc","label":"49 U.S.C. § 31100","url":"https://www.law.cornell.edu/uscode/text/49/31100","stext":{"head":"§31100. Purpose","paras":[[0,"The purpose of this subchapter is to ensure that the Secretary, States, and other political jurisdictions work in partnership to establish programs to improve motor carrier, commercial motor vehicle, and driver safety to support a safe and efficient transportation system by—"],[1,"(1) focusing resources on strategic safety investments to promote safe for-hire and private transportation, including transportation of passengers and hazardous materials, to identify high-risk carriers and drivers, and to invest in activities likely to generate maximum reductions in the number and severity of commercial motor vehicle crashes;"],[1,"(2) increasing administrative flexibility and developing and enforcing effective, compatible, and cost-beneficial motor carrier, commercial motor vehicle, and driver safety regulations and practices, including improving enforcement of State and local traffic safety laws and regulations;"],[1,"(3) assessing and improving statewide program performance by setting program outcome goals, improving problem identification and countermeasures planning, designing appropriate performance standards, measures, and benchmarks, improving performance information and analysis systems, and monitoring program effectiveness;"],[1,"(4) ensuring that drivers of commercial motor vehicles and enforcement personnel obtain adequate training in safe operational practices and regulatory requirements; and"],[1,"(5) advancing promising technologies and encouraging adoption of safe operational practices."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/49/31100?type=usc&year=mostrecent&link-type=html"},"head":"§31100. Purpose","tname":"Transportation","by":{"0":"43","1":"51"}},{"t":"usc","label":"49 U.S.C. § 31136","url":"https://www.law.cornell.edu/uscode/text/49/31136","subs":["(a)(5)","(c)(2)","(a)"],"stext":{"head":"§31136. United States Government regulations","paras":[[0,"(a) Minimum Safety Standards.—Subject to section 30103(a) of this title, the Secretary of Transportation shall prescribe regulations on commercial motor vehicle safety. The regulations shall prescribe minimum safety standards for commercial motor vehicles. At a minimum, the regulations shall ensure that—"],[1,"(1) commercial motor vehicles are maintained, equipped, loaded, and operated safely;"],[1,"(2) the responsibilities imposed on operators of commercial motor vehicles do not impair their ability to operate the vehicles safely;"],[1,"(3) the physical condition of operators of commercial motor vehicles is adequate to enable them to operate the vehicles safely and the periodic physical examinations required of such operators are performed by medical examiners who have received training in physical and medical examination standards and, after the national registry maintained by the Department of Transportation under section 31149(d) is established, are listed on such registry;"],[1,"(4) the operation of commercial motor vehicles does not have a deleterious effect on the physical condition of the operators; and"],[1,"(5) an operator of a commercial motor vehicle is not coerced by a motor carrier, shipper, receiver, or transportation intermediary to operate a commercial motor vehicle in violation of a regulation promulgated under this section, or chapter 51 or chapter 313 of this title."],[0,"(b) Eliminating and Amending Existing Regulations.—The Secretary may not eliminate or amend an existing motor carrier safety regulation related only to the maintenance, equipment, loading, or operation (including routing) of vehicles carrying material found to be hazardous under section 5103 of this title until an equivalent or more stringent regulation has been prescribed under section 5103."],[0,"(c) Procedures and Considerations.—(1) A regulation under this section shall be prescribed under section 553 of title 5 (without regard to sections 556 and 557 of title 5)."],[0,"(2) Before prescribing regulations under this section, the Secretary shall consider, to the extent practicable and consistent with the purposes of this chapter—"],[1,"(A) costs and benefits; and"],[1,"(B) State laws and regulations on commercial motor vehicle safety, to minimize their unnecessary preemption."],[0,"(d) Effect of Existing Regulations.—If the Secretary does not prescribe regulations on commercial motor vehicle safety under this section, regulations on commercial motor vehicle safety prescribed by the Secretary before October 30, 1984, and in effect on October 30, 1984, shall be deemed in this subchapter to be regulations prescribed by the Secretary under this section."],[0,"(e) Exemptions.—The Secretary may grant in accordance with section 31315 waivers and exemptions from, or conduct pilot programs with respect to, any regulations prescribed under this section."],[0,"(f) Regulatory Impact Analysis.—"],[1,"(1) In general.—Within each regulatory impact analysis of a proposed or final major rule issued by the Federal Motor Carrier Safety Administration, the Secretary shall, whenever practicable—"],[2,"(A) consider the effects of the proposed or final rule on different segments of the motor carrier industry; and"],[2,"(B) formulate estimates and findings based on the best available science."],[1,"(2) Scope.—To the extent feasible and appropriate, and consistent with law, an analysis described in paragraph (1) shall—"],[2,"(A) use data that is representative of commercial motor vehicle operators or motor carriers, or both, that will be impacted by the proposed or final rule; and"],[2,"(B) consider the effects on commercial truck and bus carriers of various sizes and types."],[0,"(g) Public Participation.—"],[1,"(1) In general.—If a proposed rule under this part is likely to lead to the promulgation of a major rule, the Secretary, before publishing such proposed rule, shall—"],[2,"(A) issue an advance notice of proposed rulemaking; or"],[2,"(B) proceed with a negotiated rulemaking."],[1,"(2) Requirements.—Each advance notice of proposed rulemaking issued under paragraph (1) shall—"],[2,"(A) identify the need for a potential regulatory action;"],[2,"(B) identify and request public comment on the best available science or technical information relevant to analyzing potential regulatory alternatives;"],[2,"(C) request public comment on the available data and costs with respect to regulatory alternatives reasonably likely to be considered as part of the rulemaking; and"],[2,"(D) request public comment on available alternatives to regulation."],[1,"(3) Waiver.—This subsection does not apply to a proposed rule if the Secretary, for good cause, finds (and incorporates the finding and a brief statement of reasons for such finding in the proposed or final rule) that an advance notice of proposed rulemaking is impracticable, unnecessary, or contrary to the public interest."],[0,"(h) Rule of Construction.—Nothing in subsection (f) or (g) may be construed to limit the contents of an advance notice of proposed rulemaking."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/49/31136?type=usc&year=mostrecent&link-type=html"},"head":"§31136. United States Government regulations","tname":"Transportation","by":{"0":"10, 33, 40","1":"45","2":"4","3":"7, 14, 14"}},{"t":"usc","label":"49 U.S.C. § 41713","url":"https://www.law.cornell.edu/uscode/text/49/41713","subs":["(b)(1)"],"stext":{"head":"§41713. Preemption of authority over prices, routes, and service","paras":[[0,"(a) Definition.—In this section, \"State\" means a State, the District of Columbia, and a territory or possession of the United States."],[0,"(b) Preemption.—(1) Except as provided in this subsection, a State, political subdivision of a State, or political authority of at least 2 States may not enact or enforce a law, regulation, or other provision having the force and effect of law related to a price, route, or service of an air carrier that may provide air transportation under this subpart."],[0,"(2) Paragraphs (1) and (4) of this subsection do not apply to air transportation provided entirely in Alaska unless the transportation is air transportation (except charter air transportation) provided under a certificate issued under section 41102 of this title."],[0,"(3) This subsection does not limit a State, political subdivision of a State, or political authority of at least 2 States that owns or operates an airport served by an air carrier holding a certificate issued by the Secretary of Transportation from carrying out its proprietary powers and rights."],[0,"(4) Transportation by air carrier or carrier affiliated with a direct air carrier.—"],[1,"(A) General rule.—Except as provided in subparagraph (B), a State, political subdivision of a State, or political authority of 2 or more States may not enact or enforce a law, regulation, or other provision having the force and effect of law related to a price, route, or service of an air carrier or carrier affiliated with a direct air carrier through common controlling ownership when such carrier is transporting property by aircraft or by motor vehicle (whether or not such property has had or will have a prior or subsequent air movement)."],[1,"(B) Matters not covered.—Subparagraph (A)—"],[2,"(i) shall not restrict the safety regulatory authority of a State with respect to motor vehicles, the authority of a State to impose highway route controls or limitations based on the size or weight of the motor vehicle or the hazardous nature of the cargo, or the authority of a State to regulate motor carriers with regard to minimum amounts of financial responsibility relating to insurance requirements and self-insurance authorization; and"],[2,"(ii) does not apply to the transportation of household goods, as defined in section 13102 of this title."],[1,"(C) Applicability of paragraph (1).—This paragraph shall not limit the applicability of paragraph (1)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/49/41713?type=usc&year=mostrecent&link-type=html"},"head":"§41713. Preemption of authority over prices, routes, and service","tname":"Transportation","by":{"0":"5, 6, 27, 45","1":"24","2":"5, 11, 15, 16"}},{"t":"law","label":"Pub. L. No. 89-670","url":"https://www.govinfo.gov/link/statute/80/931","by":{"0":"6, 7, 24"}},{"t":"law","label":"Pub. L. No. 95-504","url":"https://www.govinfo.gov/link/statute/92/1705","by":{"0":"5, 6, 24","2":"4"}},{"t":"law","label":"Pub. L. No. 96-296","url":"https://www.govinfo.gov/link/statute/94/793","by":{"0":"6, 7","1":"4, 19, 4","2":"5"}},{"t":"law","label":"Pub. L. No. 103-272","url":"https://www.govinfo.gov/link/statute/108/745","by":{"0":"9, 24"}},{"t":"law","label":"Pub. L. No. 103-305","url":"https://www.govinfo.gov/link/statute/108/1569","by":{"0":"7","1":"4, 4","2":"21"}},{"t":"law","label":"Pub. L. No. 104-88","url":"https://www.govinfo.gov/link/plaw/104/public/88","by":{"0":"24, 31","1":"42, 43"}},{"t":"law","label":"Pub. L. No. 105-178","url":"https://www.govinfo.gov/link/plaw/105/public/178","by":{"0":"9, 10, 24"}},{"t":"law","label":"Pub. L. No. 106-159","url":"https://www.govinfo.gov/link/plaw/106/public/159","by":{"0":"10, 24"}},{"t":"reg","label":"49 C.F.R. § 371.1","url":"https://www.ecfr.gov/current/title-49/section-371.1","by":{"0":"10"}},{"t":"reg","label":"49 C.F.R. § 371.7","url":"https://www.ecfr.gov/current/title-49/section-371.7","by":{"0":"10"}},{"t":"reg","label":"49 C.F.R. § 390.13","url":"https://www.ecfr.gov/current/title-49/section-390.13","by":{"0":"33"}},{"t":"reg","label":"49 C.F.R. § 395.22","url":"https://www.ecfr.gov/current/title-49/section-395.22","by":{"0":"10"}},{"t":"reg","label":"49 C.F.R. § 395.3","url":"https://www.ecfr.gov/current/title-49/section-395.3","by":{"0":"10"}},{"t":"case","label":"U.S.Br., C.H. Robinson Worldwide, Inc. v. Miller","cite":"2022 WL 1670803","y":2022,"court":"U.S. filed May 24","by":{"0":"21, 49"}},{"t":"case","label":"Am. Trucking Ass’ns, Inc. v. City of Los Angeles","cite":"569 U.S. 641","y":2013,"id":"2012/11-798","sc":1,"op":1,"sum":"The Court held that when a municipal government is acting as a contract-based participant in the market, as opposed to a market regulator, it could not regulate motor carrier activities.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Am. Trucking Ass’ns, Inc. v. United States","cite":"344 U.S. 298","y":1953,"id":"scdb/1952-032","sc":1,"sum":"Under the Motor Carrier Act, 1935, as amended, the Interstate Commerce Commission promulgated rules governing the use by authorized motor carriers of equipment not owned by them but leased from the owners or obtained by interchange with other authorized motor carriers. These rules abolish trip-leasing and revenue-splitting with driver-owners; require written contracts, carrier inspection, control-and responsibility …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Bd. of Trs. of Univ. of Illinois v. United States","cite":"289 U.S. 48","y":1933,"id":"1900-1940/289us48","sc":1,"sum":"The Chief Justice noted that, while the laying of duties is a tax, and the power to tax and the power to regulate commerce are distinct, \"it does not follow that duties may not be imposed in the exercise of the power to regulate commerce.\" If Congress asserts that it is exercising its power under the Commerce Clause, the Court concluded, \"the judicial department may not attempt in its own conception of policy to distribute the duties thus fixed by allocating some of them to the…power to regulate commerce and others to…the taxing power.\" Therefore, because \"no State by virtue of any interest of its own would be entitled to override\" Congress' power under the Commerce Clause, the tariff may be levied.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"Beecham v. United States","cite":"511 U.S. 368","y":1994,"id":"1993/93-445","sc":1,"sum":"The Court applied the choice of law clause to the exemption clause and reasoned that no rights could be restored unless by the jurisdiction that first barred the rights. The Court ruled that though the federal government did not currently have any procedures in place to restore the civil rights of felons, only the federal government had jurisdiction over federal convictions.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Cal. Trucking Ass’n v. Su","cite":"903 F.3d 953","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/903/953/","by":{"1":"21, 51"}},{"t":"case","label":"Castle v. Hayes Freight Lines","cite":"348 U.S. 61","y":1954,"id":"1940-1955/348us61","sc":1,"ar":4,"sum":"When an interstate motor carrier holds a certificate of cdnvenience and necessity issued by the Interstate Commerce Commission under the Federal Motor Carrier Act, a state may not suspend the carrier's right to use the State's highways in its interstate operations, as punishment for repeated violations of a state law regulating the weight of loads of freight that may be carried on the State's highways.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"12, 14, 19, 20, 48","2":"29","3":"19"}},{"t":"case","label":"Chamber of Com. v. Whiting","cite":"563 U.S. 582","y":2011,"id":"2010/09-115","sc":1,"op":2,"ar":1,"sum":"The Court held that Arizona laws requiring employers to verify the employment eligibility of their employees through a federal database was not unconstitutional.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Charleston & W. Carolina Ry. Co. v. Varnville Furniture Co.","cite":"237 U.S. 597","y":1915,"id":"scdb/1914-122","sc":1,"sum":"A state law not contrived in aid of the policies of Congress, but to enforce a policy of the State differently conceived, cannot be said to be in aid of interstate commerce.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"41"}},{"t":"case","label":"Chisom v. Roemer","cite":"501 U.S. 380","y":1991,"id":"1990/90-757","sc":1,"sum":"The Court determined that if Congress had that aim, it would have indicated this exclusion explicitly. Consequently, the Court favored a broad interpretation of the word \"representative\" in section 2 of the Voting Rights Act, considering it to encompass all winners of popular elections.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Cont’l Baking Co. v. Woodring","cite":"286 U.S. 352","y":1932,"id":"scdb/1931-105","sc":1,"sum":"that the exemption is not so uncertain as to render the tax void.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"47"}},{"t":"case","label":"Dubin v. United States","cite":"599 U.S. 110","y":2023,"id":"2022/22-10","sc":1,"op":1,"sum":"Under 18 U. S. C. §1028A(a)(1)’s crime of “aggravated identity theft,” a defendant “uses” another person’s means of identification “in relation to” a predicate offense when the use is at the crux of what makes the conduct criminal.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"29, 30"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Gamble v. I.C.C.","cite":"636 F.2d 1101","y":1981,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/636/1101/","by":{"1":"19"}},{"t":"case","label":"Geier v. Am. Honda Motor Co.","cite":"529 U.S. 861","y":2000,"id":"1999/98-1811","sc":1,"sum":"The Court held that \"[Geier's] 'no airbag' lawsuit conflicts with the objectives of FMVSS 208 and is therefore pre-empted by the Act.\" Justice Breyer wrote for the Court that a rule of state tort law imposing a duty to install airbags in cars such as Honda's would have presented an obstacle to the variety and mix of devices that the federal regulation sought and to the phase-in that the federal regulation deliberately imposed.","sumSrc":"Oyez","by":{"1":"37","2":"14, 29"}},{"t":"case","label":"Gustafson v. Alloyd Co.","cite":"513 U.S. 561","y":1995,"id":"1994/93-404","sc":1,"sum":"Petitioners (collectively Gustafson), the sole shareholders of Alloyd, Inc., sold substantially all of its stock to respondents and other buyers in a private sale agreement. The purchase price included a payment reflecting an estimated increase in the company's net worth from the end of the previous year through the closing, since hard financial data were unavailable. The contract provided that if a year-end audit …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31"}},{"t":"case","label":"Hendrick v. Maryland","cite":"235 U.S. 610","y":1915,"id":"scdb/1914-272","sc":1,"sum":"Only those whose rights are.directly affected can properly question the constitutionality of a state statute and invoke the jurisdiction of \"this court in respect thereto.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"47"}},{"t":"case","label":"Hess v. Pawloski","cite":"274 U.S. 352","y":1927,"id":"scdb/1926-076","sc":1,"by":{"1":"47"}},{"t":"case","label":"Intel Corp. Inv. Pol’y Comm. v. Sulyma","cite":"589 U.S. 178","y":2020,"id":"2019/18-1116","sc":1,"sum":"The Court held that under the Employee Retirement Income Security Act of 1974 requirement that plaintiffs with “actual knowledge” of an alleged fiduciary breach must file suit within three years of gaining that knowledge, a plaintiff does not necessarily have “actual knowledge” of the information contained in disclosures that he receives but does not read or cannot recall reading.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Japan Line, Ltd. v. Los Angeles Cnty.","cite":"441 U.S. 434","y":1979,"id":"1978/77-1378","sc":1,"sum":"Appellant Japanese shipping companies' vessels carry cargo containers which, like the ships, are owned by appellants, are based, registered, and subjected to property tax in Japan, and are used exclusively in foreign commerce. A number of appellants' containers were temporarily present in appellee county and cities in California, and appellees levied property taxes on the containers. The California Supreme Court …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Jones v. Hendrix","cite":"599 U.S. 465","y":2023,"id":"2022/21-857","sc":1,"sum":"The saving clause in 28 U. S. C. §2255(e) does not allow a prisoner asserting an intervening change in the interpretation of a criminal statute to circumvent the Antiterrorism and Effective Death Penalty Act of 1996’s restrictions on second or successive §2255 motions by filing a habeas petition under §2241.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"38"}},{"t":"case","label":"Kane v. New Jersey","cite":"242 U.S. 160","y":1916,"id":"scdb/1916-036","sc":1,"sum":"Inregulating the use of motor vehicles upon its highways, (Hendrick v. Maryland, 235 U. S. 610), a State may require nonresident owners to appoint a state official as agent upon whom process may be served in legal proceedings brought against them, and resulting from the operation of their motor vehicles, within the State.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"47"}},{"t":"case","label":"Loughrin v. United States","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"sum":"The Court held that, to find someone guilty of bank fraud, only one of the two bank fraud statutes must be met, not both.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Maurer v. Hamilton","cite":"309 U.S. 598","y":1940,"id":"scdb/1939-077","sc":1,"sum":"1. A Pennsylvania statute prohibiting the operation on the highways of the State of any vehicle carrying any other vehicle \"above the cab of the carrier vehicle or over the head of the operator of such carrier vehicle,\" and applied to interstate carriers, held consistent with due process of law, and consistent with the commerce clause in the absence of Congressional action.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"47"}},{"t":"case","label":"McDonnell v. United States","cite":"579 U.S. 550","y":2016,"id":"2015/15-474","sc":1,"sum":"The Court held that, for the purpose of federal bribery statutes, an “official act” is a decision or action on a question, matter, cause, suit, proceeding, or controversy that involves a specific exercise of formal governmental power.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Montgomery v. Caribe Transp. II, LLC","cite":"2023 WL 7280899","y":2023,"court":"S.D. Ill. Nov. 3","by":{"1":"8"}},{"t":"case","label":"Morris v. Duby","cite":"274 U.S. 135","y":1927,"id":"scdb/1926-054","sc":1,"sum":"1. The power of the States to make reasonable regulations to protect highways from damage by vehicles is not affected by the Acts of Congress providing for national and state cooperation in the construction of rural post roads.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"47"}},{"t":"case","label":"Nat’l R.R. Passenger Corp. v. Nat’l Ass’n of R.R. Passengers","cite":"414 U.S. 453","y":1974,"id":"1973/72-1289","sc":1,"sum":"Section: 307 (a), in light of its express language, and the legislative history of that provision 'and of the Act as a *whole, provides the exclusive remedies for breaches of any duties or obligations imposed by the Act, and no additional private cause of action to enforce compliance with the Act can properly be inferred. Pp. 455-465. 154 U. S. App. D. C.-214, 475 F. 2d 325,.reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"New England Power Co. v. New Hampshire","cite":"455 U.S. 331","y":1982,"id":"1981/80-1208","sc":1,"sum":"New Hampshire has sought to restrict the flow of privately owned and produced electricity in interstate commerce in a manner inconsistent with the Commerce Clause. Section 201(b) of the Federal Power Act does not provide an affirmative grant of authority to the State to do so.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"46"}},{"t":"case","label":"Oneok, Inc. v. Learjet, Inc.","cite":"575 U.S. 373","y":2015,"id":"2014/13-271","sc":1,"sum":"The Court held that the Natural Gas Act does not pre-empt state law claims brought by litigants who purchased gas in retail transactions.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Pereira v. Sessions","cite":"585 U.S. 198","y":2018,"id":"2017/17-459","sc":1,"sum":"The Court held that a notice to appear for a removal hearing that does not specify the place and time of the hearing does not trigger the stop-time rule of 8 U.S.C. § 1229b(b)(1), which gives the attorney general discretion to cancel removal for an alien who, among other criteria, has been continuously physically present in the country for at least ten years.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Pilot Life Ins. Co. v. Dedeaux","cite":"481 U.S. 41","y":1987,"id":"1986/85-1043","sc":1,"sum":"ERISA pre-empts respondent's suit under state common law for alleged improper processing of his claim for benefits under the ERISAregulated benefit plan.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13, 29, 36, 37","2":"11"}},{"t":"case","label":"Puerto Rico v. Franklin Cal. Tax-free Tr.","cite":"579 U.S. 115","y":2016,"id":"2015/15-233","sc":1,"sum":"The Court determined that Chapter 9 of the Bankruptcy Code preempted the Puerto Rico statute that allowed public utilities to restructure their debt.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Rudisill v. McDonough","cite":"601 U.S. 294","y":2024,"id":"2023/22-888","sc":1,"sum":"Servicemembers who, through separate periods of service, accrue educational benefits under both the Montgomery and Post-9/11 GI Bills may use either one, in any order, up to 38 U. S. C. §3695(a)’s 48-month aggregate-benefits cap.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"36"}},{"t":"case","label":"Sackett v. EPA","cite":"598 U.S. 651","y":2023,"id":"2022/21-454","sc":1,"sum":"The Clean Water Act extends only to wetlands that have a continuous surface connection with “waters” of the United States—i.e., with a relatively permanent body of water connected to traditional interstate navigable waters, 33 U. S. C. §1362(7)—making it difficult to determine where the water ends and the wetland begins.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"22"}},{"t":"case","label":"Sproles v. Binford","cite":"286 U.S. 374","y":1932,"id":"scdb/1931-073","sc":1,"sum":"(1) The limitation was within the broad discretion of the state legislature and does not violate the due process clause of the Fourteenth Amendment. P. 388. (2) In such matters the courts are not to apply scientific precision as a criterion of constitutional powers. Id.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"47"}},{"t":"case","label":"United States v. Fausto","cite":"484 U.S. 439","y":1988,"id":"1987/86-595","sc":1,"sum":"The CSRA, which affords to nonpreference eligibles in the excepted service no administrative or judicial review of adverse personnel action of the type involved here, precludes judicial review for those employees under the Tucker Act based on the Back Pay Act. The CSRA was designed to replace the haphazard arrangements that had built up over almost a century with one integrated system for administrative and judicial …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43"}},{"t":"case","label":"Virginia Uranium, Inc. v. Warren","cite":"587 U.S. 761","y":2019,"id":"2018/16-1275","sc":1,"sum":"The Fourth Circuit’s judgment that the Atomic Energy Act does not preempt Virginia’s prohibition on uranium mining in the Commonwealth is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"26","2":"21"}},{"t":"case","label":"Wyoming v. Oklahoma","cite":"502 U.S. 437","y":1992,"id":"1991/112_orig","sc":1,"sum":"Wyoming, a major coal-producing State, does not sell coal, but does impose a severance tax on those who extract it. From 1981 to 1986, Wyoming provided virtually 100% of the coal purchased by four Oklahoma electric utilities, including the Grand River Dam Authority (GRDA), a state agency. However, after the Oklahoma Legislature passed an Act requiring coal-fired electric utilities to burn a mixture containing at …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"47"}},{"t":"usc","label":"23 U.S.C. § 127","url":"https://www.law.cornell.edu/uscode/text/23/127","subs":["(1994)"],"by":{"1":"31"}},{"t":"usc","label":"49 U.S.C. § 113","url":"https://www.law.cornell.edu/uscode/text/49/113","subs":["(f)(1)"],"by":{"1":"39"}},{"t":"usc","label":"49 U.S.C. § 304","url":"https://www.law.cornell.edu/uscode/text/49/304","subs":["(a)(1)(1946)"],"by":{"1":"18"}},{"t":"usc","label":"49 U.S.C. § 306","url":"https://www.law.cornell.edu/uscode/text/49/306","subs":["(1946)"],"by":{"1":"18"}},{"t":"usc","label":"49 U.S.C. § 311","url":"https://www.law.cornell.edu/uscode/text/49/311","subs":["(1946)","(a)(1946)"],"by":{"1":"48, 40, 48"}},{"t":"usc","label":"49 U.S.C. § 315","url":"https://www.law.cornell.edu/uscode/text/49/315","subs":["(1946)"],"by":{"1":"18"}},{"t":"usc","label":"49 U.S.C. § 10922","url":"https://www.law.cornell.edu/uscode/text/49/10922","by":{"1":"19"}},{"t":"usc","label":"49 U.S.C. § 10927","url":"https://www.law.cornell.edu/uscode/text/49/10927","subs":["(a)(1)(1994)"],"by":{"1":"31"}},{"t":"usc","label":"49 U.S.C. § 11501","url":"https://www.law.cornell.edu/uscode/text/49/11501","subs":["(g)(1994)","(h)"],"by":{"1":"42, 4, 34, 43"}},{"t":"usc","label":"49 U.S.C. § 13901","url":"https://www.law.cornell.edu/uscode/text/49/13901","stext":{"head":"§13901. Requirements for registration","paras":[[0,"(a) In General.—A person may provide transportation as a motor carrier subject to jurisdiction under subchapter I of chapter 135 or service as a freight forwarder subject to jurisdiction under subchapter III of such chapter, or service as a broker for transportation subject to jurisdiction under subchapter I of such chapter only if the person is registered under this chapter to provide such transportation or service."],[0,"(b) Registration Numbers.—"],[1,"(1) In general.—If the Secretary registers a person under this chapter to provide transportation or service, including as a motor carrier, freight forwarder, or broker, the Secretary shall issue a distinctive registration number to the person for each such authority to provide transportation or service for which the person is registered."],[1,"(2) Transportation or service type indicator.—A number issued under paragraph (1) shall include an indicator of the type of transportation or service for which the registration number is issued, including whether the registration number is issued for registration of a motor carrier, freight forwarder, or broker."],[0,"(c) Specification of Authority.—For each agreement to provide transportation or service for which registration is required under this chapter, the registrant shall specify, in writing, the authority under which the person is providing such transportation or service."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/49/13901?type=usc&year=mostrecent&link-type=html"},"head":"§13901. Requirements for registration","tname":"Transportation","by":{"1":"48","2":"31"}},{"t":"usc","label":"49 U.S.C. § 13902","url":"https://www.law.cornell.edu/uscode/text/49/13902","subs":["(a)","(a)(1)(A)"],"by":{"1":"6, 6, 19, 40"}},{"t":"usc","label":"49 U.S.C. § 13903","url":"https://www.law.cornell.edu/uscode/text/49/13903","subs":["(d)"],"by":{"1":"35"}},{"t":"usc","label":"49 U.S.C. § 13905","url":"https://www.law.cornell.edu/uscode/text/49/13905","subs":["(d)"],"stext":{"head":"§13905. Effective periods of registration","paras":[[0,"(a) Person Holding ICC Authority.—Any person having authority to provide transportation or service as a motor carrier, freight forwarder, or broker under this title, as in effect on December 31, 1995, shall be deemed, for purposes of this part, to be registered to provide such transportation or service under this part."],[0,"(b) Person Registered With Secretary.—"],[1,"(1) In general.—Except as provided in paragraph (2), any person having registered with the Secretary to provide transportation or service as a motor carrier or motor private carrier under this title, as in effect on January 1, 2005, but not having registered pursuant to section 13902(a), shall be treated, for purposes of this part, to be registered to provide such transportation or service for purposes of sections 13908 and 14504a."],[1,"(2) Exclusively intrastate operators.—Paragraph (1) does not apply to a motor carrier or motor private carrier (including a transporter of waste or recyclable materials) engaged exclusively in intrastate transportation operations."],[0,"(c) Effective Period.—"],[1,"(1) In general.—Except as otherwise provided in this part, each registration issued under section 13902, 13903, or 13904—"],[2,"(A) shall be effective beginning on the date specified by the Secretary; and"],[2,"(B) shall remain in effect for such period as the Secretary determines appropriate by regulation."],[1,"(2) Reissuance of registration.—"],[2,"(A) Requirement.—Not later than 4 years after the date of enactment of the Commercial Motor Vehicle Safety Enhancement Act of 2012, the Secretary shall require a freight forwarder or broker to renew its registration issued under this chapter."],[2,"(B) Effective period.—Each registration renewal under subparagraph (A)—"],[3,"(i) shall expire not later than 5 years after the date of such renewal; and"],[3,"(ii) may be further renewed as provided under this chapter."],[0,"(d) Suspension, Amendments, and Revocations.—"],[1,"(1) Applications.—On application of the registrant, the Secretary may amend or revoke a registration."],[1,"(2) Complaints and actions on secretary's own initiative.—On complaint or on the Secretary's own initiative and after notice and an opportunity for a proceeding, the Secretary may—"],[2,"(A) suspend, amend, or revoke any part of the registration of a motor carrier, foreign motor carrier, foreign motor private carrier, broker, or freight forwarder for willful failure to comply with—"],[3,"(i) this part;"],[3,"(ii) an applicable regulation or order of the Secretary or the Board, including the accessibility requirements established by the Secretary under subpart H of part 37 of title 49, Code of Federal Regulations (or successor regulations), for transportation provided by an over-the-road bus; or"],[3,"(iii) a condition of its registration;"],[2,"(B) withhold, suspend, amend, or revoke any part of the registration of a motor carrier, foreign motor carrier, foreign motor private carrier, broker, or freight forwarder for failure—"],[3,"(i) to pay a civil penalty imposed under chapter 5, 51, 149, or 311;"],[3,"(ii) to arrange and abide by an acceptable payment plan for such civil penalty, not later than 90 days after the date specified by order of the Secretary for the payment of such penalty; or"],[3,"(iii) for failure 1 to obey a subpoena issued by the Secretary;"],[2,"(C) withhold, suspend, amend, or revoke any part of a registration of a motor carrier, foreign motor carrier, foreign motor private carrier, broker, or freight forwarder following a determination by the Secretary that the motor carrier, broker, or freight forwarder failed to disclose, in its application for registration, a material fact relevant to its willingness and ability to comply with—"],[3,"(i) this part;"],[3,"(ii) an applicable regulation or order of the Secretary or the Board; or"],[3,"(iii) a condition of its registration; or"],[2,"(D) withhold, suspend, amend, or revoke any part of a registration of a motor carrier, foreign motor carrier, foreign motor private carrier, broker, or freight forwarder if the Secretary finds that the motor carrier, broker, or freight forwarder does not disclose any relationship through common ownership, common management, common control, or common familial relationship to any other motor carrier, broker, or freight forwarder, or any other applicant for motor carrier, broker, or freight forwarder registration that the Secretary determines is or was unwilling or unable to comply with the relevant requirements listed in section 13902, 13903, or 13904."],[1,"(3) Limitation.—Paragraph (2)(B) shall not apply to a person who is unable to pay a civil penalty because the person is a debtor in a case under chapter 11 of title 11."],[1,"(4) Regulations.—Not later than 12 months after the date of the enactment of this paragraph, the Secretary, after notice and opportunity for public comment, shall issue regulations to provide for the suspension, amendment, or revocation of a registration under this part for failure to pay a civil penalty as provided in paragraph (2)(B)."],[0,"(e) Procedure.—Except on application of the registrant, or if the Secretary determines that the registrant failed to disclose a material fact in an application for registration in accordance with subsection (d)(2)(C), the Secretary may revoke a registration of a motor carrier, freight forwarder, or broker, only after—"],[1,"(1) the Secretary has issued an order to the registrant under section 14701 requiring compliance with this part, a regulation of the Secretary, or a condition of the registration; and"],[1,"(2) the registrant willfully does not comply with the order for a period of 30 days."],[0,"(f) Expedited Procedure.—"],[1,"(1) Protection of safety.—Notwithstanding subchapter II of chapter 5 of title 5, the Secretary—"],[2,"(A) may suspend the registration of a motor carrier, a freight forwarder, or a broker for failure to comply with requirements of the Secretary pursuant to section 13904(e) or 13906 or an order or regulation of the Secretary prescribed under those sections; and"],[2,"(B) shall revoke the registration of a motor carrier that has been prohibited from operating in interstate commerce for failure to comply with the safety fitness requirements of section 31144."],[1,"(2) Imminent hazard to public health.—Notwithstanding subchapter II of chapter 5 of title 5, the Secretary shall revoke the registration of a motor carrier if the Secretary finds that the carrier is or was conducting unsafe operations that are or were an imminent hazard to public health or property."],[1,"(3) Notice; period of suspension.—The Secretary may suspend or revoke under this subsection the registration only after giving notice of the suspension or revocation to the registrant. A suspension remains in effect until the registrant complies with the applicable sections or, in the case of a suspension under paragraph (2), until the Secretary revokes the suspension."],[0,"(g) Mexico-Domiciled Motor Carriers.—Notwithstanding any other provision of this section, upon an order in accordance with section 324(a) of the United States-Mexico-Canada Agreement Implementation Act, the Secretary shall carry out the relief specified by revoking or imposing limitations on existing registrations of Mexico-domiciled motor carriers of cargo to operate beyond the municipalities along the United States-Mexico international border and the commercial zones of those municipalities as directed."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/49/13905?type=usc&year=mostrecent&link-type=html"},"head":"§13905. Effective periods of registration","tname":"Transportation","by":{"1":"19","2":"31, 31"}},{"t":"usc","label":"49 U.S.C. § 30102","url":"https://www.law.cornell.edu/uscode/text/49/30102","subs":["(9)"],"by":{"1":"39"}},{"t":"usc","label":"49 U.S.C. § 31111","url":"https://www.law.cornell.edu/uscode/text/49/31111","by":{"1":"31"}},{"t":"usc","label":"49 U.S.C. § 31113","url":"https://www.law.cornell.edu/uscode/text/49/31113","by":{"1":"31"}},{"t":"usc","label":"49 U.S.C. § 31134","url":"https://www.law.cornell.edu/uscode/text/49/31134","by":{"1":"6"}},{"t":"usc","label":"49 U.S.C. § 31139","url":"https://www.law.cornell.edu/uscode/text/49/31139","subs":["(b)"],"by":{"1":"2, 6"}},{"t":"usc","label":"49 U.S.C. § 31142","url":"https://www.law.cornell.edu/uscode/text/49/31142","by":{"1":"52"}},{"t":"usc","label":"49 U.S.C. § 41112","url":"https://www.law.cornell.edu/uscode/text/49/41112","subs":["(a)"],"stext":{"head":"§41112. Liability insurance and financial responsibility","paras":[[0,"(a) Liability Insurance.—The Secretary of Transportation may issue a certificate to a citizen of the United States to provide air transportation as an air carrier under section 41102 of this title only if the citizen complies with regulations and orders of the Secretary governing the filing of an insurance policy or self-insurance plan approved by the Secretary. The policy or plan must be sufficient to pay, not more than the amount of the insurance, for bodily injury to, or death of, an individual or for loss of, or damage to, property of others, resulting from the operation or maintenance of the aircraft under the certificate. A certificate does not remain in effect unless the carrier complies with this subsection."],[0,"(b) Financial Responsibility.—To protect passengers and shippers using an aircraft operated by an air carrier issued a certificate under section 41102 of this title, the Secretary may require the carrier to file a performance bond or equivalent security in the amount and on terms the Secretary prescribes. The bond or security must be sufficient to ensure the carrier adequately will pay the passengers and shippers when the transportation the carrier agrees to provide is not provided. The Secretary shall prescribe the amounts to be paid under this subsection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/49/41112?type=usc&year=mostrecent&link-type=html"},"head":"§41112. Liability insurance and financial responsibility","tname":"Transportation","by":{"1":"12, 25","2":"17"}},{"t":"reg","label":"49 C.F.R. pt. 365","url":"https://www.ecfr.gov/current/title-49/part-365","by":{"1":"6, 7, 19"}},{"t":"reg","label":"49 C.F.R. pt. 384","url":"https://www.ecfr.gov/current/title-49/part-384","by":{"1":"52"}},{"t":"reg","label":"49 C.F.R. § 371.2","url":"https://www.ecfr.gov/current/title-49/section-371.2","by":{"1":"7, 17, 19, 40, 48"}},{"t":"reg","label":"49 C.F.R. § 371.3","url":"https://www.ecfr.gov/current/title-49/section-371.3","subs":["(a)"],"by":{"1":"7, 19, 48, 39"}},{"t":"reg","label":"49 C.F.R. § 385.13","url":"https://www.ecfr.gov/current/title-49/section-385.13","by":{"1":"19"}},{"t":"reg","label":"49 C.F.R. § 387.1","url":"https://www.ecfr.gov/current/title-49/section-387.1","by":{"1":"40"}},{"t":"reg","label":"49 C.F.R. § 392.1","url":"https://www.ecfr.gov/current/title-49/section-392.1","subs":["(a)"],"by":{"1":"39"}},{"t":"reg","label":"49 C.F.R. § 392.9a","url":"https://www.ecfr.gov/current/title-49/section-392.9a","subs":["(a)"],"by":{"1":"6, 19"}},{"t":"reg","label":"49 C.F.R. § 392.9b","url":"https://www.ecfr.gov/current/title-49/section-392.9b","by":{"1":"6"}},{"t":"reg","label":"61 Fed. Reg. 57,252","url":"https://www.govinfo.gov/link/fr/61/57252","by":{"1":"5"}},{"t":"reg","label":"61 Fed. Reg. 57,253","url":"https://www.govinfo.gov/link/fr/61/57253","by":{"1":"5"}},{"t":"case","label":"C.H. Robinson Worldwide, Inc. v. Miller","cite":"142 S. Ct. 2866","y":2022,"url":"https://www.courtlistener.com/c/S.%20Ct./142/2866/","sc":1,"by":{"2":"2, 4"}},{"t":"case","label":"CSX Transportation, Inc. v. Easterwood","cite":"507 U.S. 658","y":1993,"id":"1992/91-790","sc":1,"op":3,"ar":4,"sum":"Under the FRSA, federal regulations adopted by the Secretary of Transportation pre-empt Easterwood's negligence action only insofar as it asserts that CSX's train was traveling at an excessive speed.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"11"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"San Diego Building Trades Council v. Garmon","cite":"359 U.S. 236","y":1959,"id":"1958/66","sc":1,"sum":"Although the National Labor Relations Board had declined to exercise jurisdiction, a California state court was precluded by the National Labor Relations Act from awarding damages to respondents under state law for economic injuries resulting from the peaceful picketing of their plant by labor unions which had not been selected by a majority of respondents' employees as their bargaining agents.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21"}},{"t":"usc","label":"29 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/29/1001","by":{"2":"11"}},{"t":"law","label":"Federal Railroad Safety Act, Pub. L. No. 91-458","url":"https://www.govinfo.gov/link/statute/84/971","by":{"2":"11"}},{"t":"law","label":"Pub. L. No. 89-564","url":"https://www.govinfo.gov/link/statute/80/731","by":{"2":"31"}},{"t":"law","label":"Pub. L. No. 98-554","url":"https://www.govinfo.gov/link/statute/98/2832","by":{"2":"2"}},{"t":"law","label":"Pub. L. No. 89-563","url":"https://www.govinfo.gov/link/statute/80/718","by":{"2":"30"}},{"t":"law","label":"Pub. L. No. 91-222","url":"https://www.govinfo.gov/link/statute/84/87","by":{"2":"11"}},{"t":"usc","label":"8 U.S.C. § 1324a","url":"https://www.law.cornell.edu/uscode/text/8/1324a","by":{"2":"30"}},{"t":"case","label":"Miller v. Costco Wholesale Corp.","cite":"2022 WL 526140","y":2022,"court":"D. Nev. Feb. 22","sum":"Finding jury question as to whether broker knowingly hired a chameleon carrier, resulting in a motor vehicle collision rendering a 25year-old man quadriplegic.","sumSrc":"brief:3","by":{"3":"7"}},{"t":"reg","label":"49 C.F.R. pt. 1043","url":"https://www.ecfr.gov/current/title-49/part-1043","by":{"3":"18"}}]};